#!/usr/bin/env bash
# Tier 1: README.md's registry table is a render of registry/*.toml and the cards they point to, never a second source. The real README matches the generated table, every guideline is linked from it, and the check is shown able to
# fail: a hand-edited score, a hand-edited date, a stale table after an entry changes, missing markers, an entry whose result or pinned commit disagrees with its card, a missing card; an unscored entry renders as unscored;
# `--write` repairs drift and never truncates the file.
export LC_ALL=C
set -euo pipefail
cd "$(dirname "$0")/.."
. scripts/lib-ran.sh   # ran_case counts each executed check, ran_done prints the evidence line `ran: NAME: N cases` (docs/0001-ran-evidence.md)
rt=$(pwd)/scorecard/registry-table
fail() { echo "tier1: readme: $*" >&2; exit 1; }
"$rt" --check README.md && ran_case || fail "README.md differs from the table generated from registry/*.toml"
pre='^\*Scored before the honesty check (ran-evidence): Process honesty here does not include it.\*$'   # the header is exactly for a card WITHOUT the ran-evidence metric (DECISIONS 19), and only for one
if grep -q '"honesty.selftests_ran_cases"' registry/scores/witt3rd__vbm-json.json; then ! grep -q "$pre" registry/scores/witt3rd__vbm-json.md && ran_case || fail "a card with the ran-evidence metric carries the pre-honesty header"
else grep -q "$pre" registry/scores/witt3rd__vbm-json.md && ran_case || fail "the pre-honesty registry card does not say so in its header (DECISIONS 19)"; fi
for g in guidelines/*.md; do [ "$g" = guidelines/INDEX.md ] || grep -q "($g)" README.md && ran_case || fail "README.md does not link the guideline $g"; done
T=$(mktemp -d); trap 'rm -rf "$T"' EXIT; mkdir -p "$T/registry/scores"
card() {   # card VELOCITY-METRIC COMMIT: a minimal card; correctness: verified passes, honesty fails (so Correctness FAILS); velocity is the given metric's dimension (the retired id: Landedness pending)
  python3 - "$1" "$2" > "$T/registry/scores/acme__widget.json" <<'PY'
import json, sys
d = lambda st, bf=[]: {"status": st, "below_floor": bf, "below_floor_implemented": bf}
print(json.dumps({"schema": "scorecard-3", "scorecard": {"sha": "s" * 40}, "adapter": {"sha256": "a" * 64}, "subject": {"name": "widget", "commit": sys.argv[2]}, "metrics": [{"id": sys.argv[1], "dimension": "velocity", "status": "pass", "value": 1, "floor": None, "definition": "A test metric. More."}], "dimensions": {"verified": d("pass"), "velocity": d("pass"), "honesty": d("fail", ["honesty.x"]), "efficiency": d("fail")}}))
PY
}
sha=$(printf 'a%.0s' $(seq 40))
entry() { cat > "$T/registry/acme__widget.toml" <<TOML
kind = "library"
status = "live"
what = "A widget"
milestone = "m"
depends_on = []
repo = "https://github.com/acme/widget"
commit = "${3:-$sha}"
targets = ["C", "Rust"]
adapter = "scorecard.toml"

[latest]
date = "2026-11-04"
correctness = "$1"
landedness = "$2"
level = "none"
card = "registry/scores/acme__widget.json"
TOML
}
printf 'intro\n<!-- registry:begin (generated by scorecard/registry-table from registry/*.toml; do not edit by hand) -->\nSTALE\n<!-- registry:end -->\noutro\n' > "$T/README.md"
card velocity.tier1_seconds "$sha"; entry fail pending
"$rt" --root "$T" --write README.md; "$rt" --root "$T" --check README.md && ran_case || fail "a freshly written README does not check"
grep -q '| \[widget\](https://github.com/acme/widget) | A widget | library | live | \*\*FAIL\*\* (2 of 4; Trusted generation not yet defined) | pending | \[card\](registry/scores/acme__widget.md) |' "$T/README.md" && ran_case || fail "the row is not rendered as expected: $(sed -n 3,6p "$T/README.md")"
grep -q '^intro$' "$T/README.md" && grep -q '^outro$' "$T/README.md" && ran_case || fail "--write damaged the text around the table"
cp "$T/README.md" "$T/README.good"
chk() { "$rt" --root "$T" --check README.md >/dev/null 2>"$T/err" && fail "negative self-test: $1 was NOT caught"; grep -q "$2" "$T/err" && ran_case || fail "$1: wrong message: $(cat "$T/err")"; }
sed -i 's/| \*\*FAIL\*\* (2 of 4; Trusted generation not yet defined) | pending |/| **PASS** | pending |/' "$T/README.md"; chk "a hand-edited score" "differs from the table"; cp "$T/README.good" "$T/README.md"
sed -i 's/ (2 of 4; Trusted generation not yet defined)//' "$T/README.md"; chk "a Correctness verdict stripped of its coverage statement" "differs from the table"; cp "$T/README.good" "$T/README.md"
grep -q '\*\*FAIL\*\* (2 of 4; Trusted generation not yet defined) | pending' "$T/README.md" && ! grep -q '| \*\*PASS\*\* |' "$T/README.md" && ran_case || fail "the registry column does not state the Correctness coverage"
pg="$T/registry/scores/acme__widget.md"
[ -f "$pg" ] && grep -q '^\*\*Correctness: ❌ FAIL\*\*' "$pg" && grep -q 'Raw JSON' "$pg" && ran_case || fail "the card page is not written with its verdict lines and the JSON link: $(head -5 "$pg")"
cp "$pg" "$T/page.good"
sed -i 's/Correctness: ❌ FAIL/Correctness: ✅ PASS/' "$pg"; chk "a hand-edited card page" "card page is a render\|differs from the page"; cp "$T/page.good" "$pg"
sed -i 's/"value": 1,/"value": 2,/' "$T/registry/scores/acme__widget.json"; grep -q '"value": 2,' "$T/registry/scores/acme__widget.json" && ran_case || fail "the fixture JSON edit did not apply"
chk "a JSON edit without regenerating the page" "differs from the page"; "$rt" --root "$T" --write README.md; "$rt" --root "$T" --check README.md && ran_case || fail "--write did not regenerate the page after a JSON edit"
card velocity.tier1_seconds "$sha"; "$rt" --root "$T" --write README.md; cp "$T/README.md" "$T/README.good"
sed -i 's/| live |/| planned |/' "$T/README.md"; chk "a hand-edited status" "differs from the table"; cp "$T/README.good" "$T/README.md"
sed -i 's/what = "A widget"/what = "A gadget"/' "$T/registry/acme__widget.toml"; chk "a stale table after an entry changed" "differs from the table"
"$rt" --root "$T" --write README.md; "$rt" --root "$T" --check README.md && ran_case || fail "--write did not repair the drift"
grep -vq 'registry:begin' "$T/README.md" || true
printf 'no markers here\n' > "$T/nomark.md"; "$rt" --root "$T" --check nomark.md >/dev/null 2>"$T/err" && fail "negative self-test: a README without markers passed"; grep -q "markers are missing" "$T/err" && ran_case || fail "wrong message for missing markers"
entry pass pending; "$rt" --root "$T" >/dev/null 2>"$T/err" && fail "negative self-test: an entry result that disagrees with its card passed"; grep -q "disagrees with its card" "$T/err" && ran_case || fail "wrong message: $(cat "$T/err")"
entry fail pending "$(printf 'b%.0s' $(seq 40))"; "$rt" --root "$T" >/dev/null 2>"$T/err" && fail "negative self-test: an entry pinned to another commit than its card passed"; grep -q "the entry pins" "$T/err" && ran_case || fail "wrong message: $(cat "$T/err")"
entry fail pending; rm "$T/registry/scores/acme__widget.json"; "$rt" --root "$T" >/dev/null 2>"$T/err" && fail "negative self-test: a missing card passed"; grep -q "does not exist" "$T/err" && ran_case || fail "wrong message: $(cat "$T/err")"
# the two verdicts: a card with the warm/cold metrics has a judged landedness; an entry that claims another landedness than its card is caught
card velocity.tier1_seconds_warm "$sha"; entry fail pass; "$rt" --root "$T" > "$T/tbl" && ran_case || fail "a scorecard-3 card with Correctness FAIL and Landedness PASS did not render"; grep -q '| live | \*\*FAIL\*\* (2 of 4; Trusted generation not yet defined) | \*\*PASS\*\* | \[card\]' "$T/tbl" && ran_case || fail "the two verdict columns are wrong: $(cat "$T/tbl")"
entry fail pending; "$rt" --root "$T" >/dev/null 2>"$T/err" && fail "negative self-test: an entry claiming PENDING landedness for a card that judges it passed"; grep -q "landedness pending disagrees with its card (pass)" "$T/err" && ran_case || fail "wrong message: $(cat "$T/err")"
entry pending pending; "$rt" --root "$T" | grep -q '| live | pending | pending | - |' && ran_case || fail "a pending entry is not rendered as pending without a link"
rm "$T/registry/acme__widget.toml"
printf 'kind = "library"\nstatus = "coming soon"\nwhat = "Other"\nmilestone = "m"\ndepends_on = []\n' > "$T/registry/acme__other.toml"
"$rt" --root "$T" | grep -q '^| other | Other | library | coming soon | unscored | unscored | - |$' && ran_case || fail "an entry with no score is not rendered as unscored without a link"
printf 'kind = "library"\nstatus = "live"\nwhat = "Live"\nmilestone = "m"\ndepends_on = []\nrepo = "https://github.com/acme/live"\ncommit = "%s"\nmanifest = "vbm-proof.toml"\ntargets = ["C"]\n[latest]\ndate = ""\ncorrectness = "unscored"\nlandedness = "unscored"\nlevel = "unscored"\ncard = ""\n' "$sha" > "$T/registry/acme__live.toml"
"$rt" --root "$T" | grep -q '^| \[live\](https://github.com/acme/live) | Live | library | live | unscored | unscored | - |$' && ran_case || fail "a live unscored entry is not rendered as unscored with its link"
rm "$T/registry/acme__live.toml"; printf 'kind = "library"\nstatus = "planned"\nwhat = "X"\nmilestone = "m"\ndepends_on = ["zzz"]\n' > "$T/registry/acme__x.toml"
"$rt" --root "$T" >/dev/null 2>"$T/err" && fail "negative self-test: an unknown dependency passed"; grep -q "is not a listed entry" "$T/err" && ran_case || fail "wrong message: $(cat "$T/err")"
ran_done test_readme
echo "tier1: readme: the registry table is a render of registry/*.toml (one source, unscored entries included); hand edits, stale tables, missing markers, unknown dependencies and entry/card disagreements are caught: ok"
